mapper.select:
SELECT * FROM `payment_refund_order`
WHERE payment_no = #{paymentNo}
ORDER BY id DESC

SELECT
FROM `payment_refund_order` r LEFT JOIN `voucher_order` vo ON vo.order_no = r.biz_order_no LEFT JOIN `voucher` v ON v.id = vo.voucher_id LEFT JOIN `merchant` m ON m.id = r.merchant_id WHERE r.merchant_id = #{merchantId}
AND r.status = #{status}
ORDER BY r.id DESC

SELECT * FROM `payment_refund_order`
WHERE status = 'WAIT_MERCHANT_REVIEW'
  AND review_deadline IS NOT NULL
  AND review_deadline <= #{now}
ORDER BY review_deadline ASC
LIMIT #{limit}

mapper.update:
UPDATE `payment_refund_order`
SET
    status = 'REJECTED',
    current_reviewer_role = NULL,
    current_reviewer_id = NULL,
    admin_review_reason = #{adminReviewReason},
    admin_review_time = #{adminReviewTime},
    admin_reviewer_id = #{adminReviewerId}
WHERE refund_no = #{refundNo}
  AND status = #{expectedStatus}
